# Phase 2 — weekly summary job (ACT)

Makes work: a nightly job writes `exports/rating-summary.json`, one row per agent with
ratings in the past seven days: how many, and their average score.

Check: `node --test test/rating-summary.test.js` passes, and the written file matches
the spec's worked example (ratings 5, 4, 1 → three ratings, average 3.33).

Blocked by: phase 1 (`store.listRatings`, `portal.rateTicket` must exist).

## Context

- `docs/specs/csat-rating.md` requirement 5, acceptance criterion 7.
- `src/jobs/export-tickets.js` — the pattern this job follows: a pure function over
  the store, writing one JSON file to `EXPORT_DIR`, no in-repo scheduler (confirmed by
  grep: none of the three existing jobs are wired to a runner in this repo — each is
  invoked externally).
- `src/jobs/close-resolved.js:11` and `src/jobs/purge-closed.js:14` — the
  `elapsed < N_DAYS` boundary this job's exclusion mirrors (see `plan.md` validation
  question 2: age ≥ `WINDOW_DAYS` drops a rating out of the window).
- `test/export-tickets.test.js` — the temp-dir test pattern this phase's test copies.

## Files

- Create `src/jobs/rating-summary.js`.
- Create `test/rating-summary.test.js` (a dedicated file, matching the convention that
  an export-writing job gets its own test file — `close-resolved.js`/`purge-closed.js`
  don't, because their tests live in `test/tickets.test.js` alongside the ticket
  lifecycle; `export-tickets.js` does, because it writes to `exports/`).

## Steps

- [ ] 1. Create `test/rating-summary.test.js`:

  ```js
  'use strict';
  const test = require('node:test');
  const assert = require('node:assert/strict');
  const fs = require('node:fs');
  const os = require('node:os');
  const path = require('node:path');
  const { createStore } = require('../src/store');
  const { createTicket, resolveTicket } = require('../src/tickets');
  const portal = require('../src/portal');
  const { ratingSummary } = require('../src/jobs/rating-summary');

  const DAY = 24 * 60 * 60 * 1000;
  const at = (days) => new Date(Date.UTC(2026, 0, 1) + days * DAY);
  const acme = { id: 7, orgId: 1 };

  test('the weekly summary counts an agent\'s ratings from the past seven days and averages them', () => {
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'helpdesk-rating-summary-'));
    try {
      const store = createStore();
      const a = createTicket(store, { orgId: 1, customerId: 7, subject: 'Printer', body: 'x', now: at(0) });
      resolveTicket(store, a.id, 41, { now: at(0) });
      portal.rateTicket(store, acme, a.id, 5, { now: at(9) }); // age 1 day at check time
      const b = createTicket(store, { orgId: 1, customerId: 7, subject: 'Scanner', body: 'x', now: at(0) });
      resolveTicket(store, b.id, 41, { now: at(0) });
      portal.rateTicket(store, acme, b.id, 4, { now: at(7) }); // age 3 days
      const c = createTicket(store, { orgId: 1, customerId: 7, subject: 'Mouse', body: 'x', now: at(0) });
      resolveTicket(store, c.id, 41, { now: at(0) });
      portal.rateTicket(store, acme, c.id, 1, { now: at(4) }); // age 6 days
      const d = createTicket(store, { orgId: 1, customerId: 7, subject: 'Keyboard', body: 'x', now: at(0) });
      resolveTicket(store, d.id, 41, { now: at(0) });
      portal.rateTicket(store, acme, d.id, 3, { now: at(3) }); // age exactly 7 days: excluded
      const old = createTicket(store, { orgId: 1, customerId: 7, subject: 'Monitor', body: 'x', now: at(0) });
      resolveTicket(store, old.id, 41, { now: at(0) });
      portal.rateTicket(store, acme, old.id, 2, { now: at(2) }); // age 8 days: excluded

      const out = ratingSummary(store, { now: at(10), dir });
      assert.equal(out.agents, 1);
      const summary = JSON.parse(fs.readFileSync(out.file, 'utf8'));
      assert.deepEqual(summary, [{ owner_id: 41, count: 3, average: 3.33 }]);
    } finally {
      fs.rmSync(dir, { recursive: true, force: true });
    }
  });
