- [ ] 2. Create `src/jobs/rating-summary.js`:

  ```js
  'use strict';
  // Nightly. Writes exports/rating-summary.json: how many ratings each agent's tickets
  // received in the past seven days, and the average score. A rating exactly seven days
  // old has aged out of the window, matching the boundary direction close-resolved.js
  // and purge-closed.js use for their own day counts.
  const fs = require('node:fs');
  const path = require('node:path');
  const { EXPORT_DIR } = require('./export-tickets');

  const WINDOW_DAYS = 7;
  const DAY = 24 * 60 * 60 * 1000;

  function ratingSummary(store, { now = new Date(), dir = EXPORT_DIR } = {}) {
    const byOwner = new Map();
    for (const r of store.listRatings()) {
      if (!r.owner_id) continue;
      if (now.getTime() - new Date(r.rated_at).getTime() >= WINDOW_DAYS * DAY) continue;
      const entry = byOwner.get(r.owner_id) || { owner_id: r.owner_id, count: 0, total: 0 };
      entry.count += 1;
      entry.total += r.score;
      byOwner.set(r.owner_id, entry);
    }
    const summary = [...byOwner.values()].map((e) => ({
      owner_id: e.owner_id,
      count: e.count,
      average: Math.round((e.total / e.count) * 100) / 100,
    }));
    fs.mkdirSync(dir, { recursive: true });
    const file = path.join(dir, 'rating-summary.json');
    fs.writeFileSync(file, JSON.stringify(summary, null, 2) + '\n');
    return { file, agents: summary.length };
  }

  module.exports = { ratingSummary, WINDOW_DAYS };
  ```

  Evidence: `node --test` — output ends `# pass 15` `# fail 0` (14 from phase 1 + 1
  new).

- [ ] 3. `git add src/jobs/rating-summary.js test/rating-summary.test.js && git commit
      -m "jobs: write a weekly per-agent rating summary"`.

  Evidence: `git log -1 --stat` shows both files.

## Exit criteria

- `node --test` passes, 0 failures.
- `ratingSummary` excludes a rating exactly 7 days old and one 8 days old; includes
  ratings up to (not including) 7 days old.
- An unassigned ticket's rating (`owner_id` null) contributes to no agent's row.

## Risks

- None beyond phase 1's: this phase only reads what phase 1 writes.

